{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-hGmq12/src/lcs.js","content":"/**
 * Diffs one side of a three-way merge against the base, using a longest
 * common subsequence over whole lines with a deterministic tie-break:
 * matches are taken as soon as they line up, and otherwise whichever side
 * can still reach the longest remaining subsequence is advanced, with the
 * base preferred on a tie.
 */

/**
 * @param {string[]} base
 * @param {string[]} side
 * @param {'mine' | 'theirs'} sideName
 * @returns {{ side: 'mine' | 'theirs', baseStart: number, baseEnd: number, lines: string[] }[]}
 *   The stretches of `base` that this side replaces, in base order.
 */
export function diffAgainstBase(base, side, sideName) {
  const n = base.length
  const m = side.length

  // dp[i][j] is the length of the longest common subsequence of base[i:]
  // and side[j:].
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let lastBase = -1
  let lastSide = -1
  const flushGap = (endBase, endSide) => {
    const baseStart = lastBase + 1
    const baseEnd = endBase
    const sideStart = lastSide + 1
    const sideEnd = endSide
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ side: sideName, baseStart, baseEnd, lines: side.slice(sideStart, sideEnd) })
    }
  }

  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flushGap(i, j)
      lastBase = i
      lastSide = j
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  flushGap(n, m)

  return changes
}
"}

