{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-hGmq12/src/merge.js","content":"/**
 * Turns the changes mine and theirs each make against the base into the
 * regions of a three-way merge, and resolves each region.
 */

import { diffAgainstBase } from './lcs.js'

const linesEqual = (a, b) => a.length === b.length && a.every((line, index) => line === b[index])

/** Merges two change lists, sorted by base start, with mine first on a tie. */
function interleaveChanges(mineChanges, theirsChanges) {
  const result = []
  let i = 0
  let j = 0
  while (i < mineChanges.length && j < theirsChanges.length) {
    result.push(mineChanges[i].baseStart <= theirsChanges[j].baseStart ? mineChanges[i++] : theirsChanges[j++])
  }
  while (i < mineChanges.length) result.push(mineChanges[i++])
  while (j < theirsChanges.length) result.push(theirsChanges[j++])
  return result
}

/** Groups changes into regions, absorbing any change that starts at or before the region's current end. */
function groupIntoRegions(changes) {
  const regions = []
  let index = 0
  while (index < changes.length) {
    const first = changes[index]
    const region = { baseStart: first.baseStart, baseEnd: first.baseEnd, changes: [first] }
    index++
    while (index < changes.length && changes[index].baseStart <= region.baseEnd) {
      const change = changes[index]
      region.baseEnd = Math.max(region.baseEnd, change.baseEnd)
      region.changes.push(change)
      index++
    }
    regions.push(region)
  }
  return regions
}

/**
 * Reconstructs one side's lines across a region from that side's own
 * changes within it, filling the stretches it left untouched with the
 * base lines that occupy them.
 */
function stitchSide(base, region, ownChanges) {
  if (ownChanges.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const sorted = [...ownChanges].sort((a, b) => a.baseStart - b.baseStart)
  const result = []
  let pos = region.baseStart
  for (const change of sorted) {
    result.push(...base.slice(pos, change.baseStart))
    result.push(...change.lines)
    pos = change.baseEnd
  }
  result.push(...base.slice(pos, region.baseEnd))
  return result
}

/**
 * Resolves one region to a `kind` of `mine`, `theirs`, `both` or
 * `conflict`, alongside the line lists needed to render it.
 */
function resolveRegion(base, region) {
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (region.changes.length === 1) {
    const [change] = region.changes
    return { kind: change.side, resolvedLines: change.lines, mineLines: null, theirsLines: null, baseLines }
  }

  const mineLines = stitchSide(base, region, region.changes.filter(c => c.side === 'mine'))
  const theirsLines = stitchSide(base, region, region.changes.filter(c => c.side === 'theirs'))

  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', resolvedLines: mineLines, mineLines, theirsLines, baseLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', resolvedLines: theirsLines, mineLines, theirsLines, baseLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', resolvedLines: mineLines, mineLines, theirsLines, baseLines }
  return { kind: 'conflict', resolvedLines: null, mineLines, theirsLines, baseLines }
}

/**
 * Builds the ordered list of segments making up a three-way merge: stable
 * runs of base lines, and resolved regions where mine and/or theirs changed
 * the base.
 *
 * @returns {({ type: 'stable', lines: string[] } | { type: 'region' } & ReturnType<typeof resolveRegion>)[]}
 */
export function buildMergeSegments(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine, 'mine')
  const theirsChanges = diffAgainstBase(base, theirs, 'theirs')
  const regions = groupIntoRegions(interleaveChanges(mineChanges, theirsChanges))

  const segments = []
  let pos = 0
  for (const region of regions) {
    if (region.baseStart > pos) segments.push({ type: 'stable', lines: base.slice(pos, region.baseStart) })
    segments.push({ type: 'region', ...resolveRegion(base, region) })
    pos = region.baseEnd
  }
  if (pos < base.length) segments.push({ type: 'stable', lines: base.slice(pos, base.length) })

  return segments
}
"}

